import { isCardKey } from '../domain/cardKey';
import type { CardKey } from '../domain/cardKey';

/** URLs of a card's images on the app's own origin (CSP img-src 'self'; never the API's image_url, SR-1). */
export interface CardImageUrls {
  small: string;
  large: string;
}

// Generated by `npm run cards:images` (D-013 osa 4). Vite gives each file a content hash in its URL,
// so the bundle holds only these URL strings and a missing image never causes a request.
const small = import.meta.glob<string>('../assets/cards/sm/*.webp', { eager: true, query: '?url', import: 'default' });
const large = import.meta.glob<string>('../assets/cards/lg/*.webp', { eager: true, query: '?url', import: 'default' });

function keyOf(path: string): string {
  return path.slice(path.lastIndexOf('/') + 1, -'.webp'.length);
}

/** Only cards with both sizes get an image; others show the placeholder. */
const images = new Map<CardKey, CardImageUrls>();
const largeByKey = new Map(Object.entries(large).map(([path, url]) => [keyOf(path), url]));
for (const [path, url] of Object.entries(small)) {
  const key = keyOf(path);
  const largeUrl = largeByKey.get(key);
  if (isCardKey(key) && largeUrl !== undefined) images.set(key, { small: url, large: largeUrl });
}

export function getCardImage(key: CardKey): CardImageUrls | null {
  return images.get(key) ?? null;
}
